// Map free-text task-category strings from the Excel to canonical keys
function catKey(catStr){
  const s = (catStr || '').toLowerCase().trim();
  if (!s) return 'A';
  if (s.includes('business')) return 'A';
  if (s.includes('content'))  return 'B';
  if (s.includes('marketing')) return 'C';
  if (s.includes('design'))   return 'D';
  if (s.includes('web') || s.includes('website')) return 'E';
  if (s.includes('seo'))      return 'F';
  if (s.includes('event'))    return 'G';
  if (s.includes('campaign')) return 'H';
  if (s.includes('lead'))     return 'I';
  return 'A';
}

function phaseKey(phaseStr){
  const s = (phaseStr || '').toLowerCase().trim();
  if (s.includes('discovery') || s.includes('foundation') || s.includes('setup')) return 'foundation';
  if (s.includes('activation') || s.includes('launch') || s.includes('execution')) return 'activation';
  if (s.includes('growth') || s.includes('scale') || s.includes('optimisation') || s.includes('optimization')) return 'growth';
  return 'foundation';
}

