const c = (id, name, short, region, size, leadKey, spoc, status, phase, complete, inProgress, attn, tasksTotal, signedAt) => {
  const renewAt = signedAt ? signedAt.replace(/^(\d{4})/, (m) => String(Number(m)+1)) : null;
  return {
    id, name, short, region, size,
    leader: TL[leadKey].name,
    leaderColor: TL[leadKey].color,
    color: TL[leadKey].color,
    owner: spoc,
    status,
    stage: status === 'active'   ? 'Active'
         : status === 'pending'  ? 'Pending Signature'
         : status === 'prospect' ? 'Prospect'
         : 'On Hold',
    phase,
    mode: status === 'active' ? 'delivery' : 'sales',
    complete, inProgress, attn,
    tasksTotal,
    signedAt, renewAt,
  };
};

