// ─── Task helpers ─────────────────────────────────────────────────────
function fmtDate(d){ return d.toLocaleString('en-US', { month:'short', day:'numeric' }); }
function isoDate(d){ return d.toISOString().slice(0,10); }
const TODAY = new Date('2026-05-17T00:00:00');

// Adopt REAL_TASKS for every client when present, otherwise leave .tasks empty.
function adoptRealTasks(client){
  const raw = (window.REAL_TASKS[client.id] || []);
  return raw.map((t, i) => {
    const dueIso = t.end || t.start || null;
    let due = '';
    let state = '';
    let offset = 0;
    if (dueIso) {
      const d = new Date(dueIso);
      offset = Math.round((d - TODAY) / 86400000);
      due = fmtDate(d);
      if (t.status === 'completed') state = '';
      else if (offset < 0)          state = 'over';
      else if (offset <= 2)         state = 'soon';
      else                          state = 'future';
    }
    return {
      id: t.id,
      name: t.name,
      action: t.action,
      cat: catKey(t.cat),
      freq: '',
      phase: phaseKey(t.phase),
      unit: t.unit,
      priority: t.priority,
      status: t.status,
      who: t.owner || client.leader,
      whoColor: client.leaderColor,
      due,
      dueIso,
      start: t.start,
      offset,
      state,
      done: t.status === 'completed',
    };
  });
}

CLIENTS.forEach(client => {
  client.tasks = adoptRealTasks(client);
  const firstOpen = client.tasks.find(t => !t.done);
  if (firstOpen) {
    client.nextTask = firstOpen.name;
    client.nextWhen = firstOpen.dueIso;
    client.nextRole = (SOW_CATEGORIES[firstOpen.cat] || {}).label || '';
    client.nextCat  = firstOpen.cat;
  } else {
    client.nextTask = null;
    client.nextWhen = null;
    client.nextRole = null;
  }
});

window.CLIENTS = CLIENTS;

// ─── Per-client drill-in details (timelines) ──────────────────────────
function genTimelineFor(client){
  const tl = [];
  const open = client.tasks.filter(t => !t.done).slice(0, 4);
  const done = client.tasks.filter(t =>  t.done).slice(0, 3);
  const fmt = (iso) => {
    if (!iso) return '—';
    const d = new Date(iso);
    const diff = Math.round((d - TODAY) / 86400000);
    if (diff === 0) return 'TODAY';
    if (diff === 1) return 'TOMORROW';
    if (diff === -1) return 'YESTERDAY';
    return d.toLocaleString('en-US',{month:'short',day:'numeric'}).toUpperCase();
  };
  open.forEach((t, i) => {
    tl.push({ when: fmt(t.dueIso), what: t.name, by: t.who, active: i === 0 });
  });
  done.forEach(t => {
    tl.push({ when: fmt(t.dueIso), what: `${t.name} — completed`, by: t.who });
  });
  return tl;
}

window.CLIENT_DETAILS = {};
CLIENTS.forEach(client => {
  window.CLIENT_DETAILS[client.id] = {
    contract: {
      value: 0,
      start: client.signedAt,
      renew: client.renewAt,
      term: '12 months',
    },
    contact: {
      primary: client.owner,
      email: `${(client.owner||'').toLowerCase().replace(/[^a-z]+/g,'.').replace(/^\.|\.$/g,'')}@${client.id}.example`,
      role: 'Customer SPOC',
    },
    tasks: client.tasks,
    timeline: genTimelineFor(client),
  };
});

// The views read the portfolio through `window` (the shape the prototype was
// written against), so keep those assignments above and re-export the same
// objects for code that prefers explicit imports.
export {
  TL as TEAM_LEADERS,
  SOW_CATEGORIES,
  CLIENTS,
  catKey,
  phaseKey,
};
export const REAL_TASKS = window.REAL_TASKS;
export const CLIENT_DETAILS = window.CLIENT_DETAILS;
